              <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse" /> {t('8 / 8 Branches Online')}
            </span>
          </div>
        </header>

        <div className="p-8">
          {mainTab === 'rates' && <GlobalSettings currentTab='rates' />}
          {mainTab === 'account_types' && <GlobalSettings currentTab='account_types' />}
          {mainTab === 'settings' && <GlobalSettings currentTab='settings' />}
          {mainTab === 'overview' && (
            activeBranch ? (
              (activeTab === 'staff' || activeTab === 'config') ? (
                <BranchDetail branch={activeBranch} allUsers={allUsers} onRefresh={fetchUsers} onBack={() => setActiveBranch(null)} innerTab={activeTab === 'staff' ? 'users' : 'config'} />
              ) : (
                <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden h-[calc(100vh-12rem)] flex flex-col">
                  <div className="flex-1 min-h-0 overflow-hidden flex flex-col">
